    $assertPaymentAgency=function(int $paymentId,string $label)use($assert,$agencyId){$row=dbFetchOne("SELECT p.agency_id,p.reservation_id,p.invoice_id,r.agency_id reservation_agency,i.agency_id invoice_agency FROM payments p LEFT JOIN reservations r ON r.id=p.reservation_id LEFT JOIN invoices i ON i.id=p.invoice_id WHERE p.id=:id",['id'=>$paymentId]);$assert($row&&((int)$row['agency_id']===$agencyId),$label.' payment row is not in the authoritative agency');$assert(!$row||$row['reservation_id']===null||(int)$row['reservation_agency']===$agencyId,$label.' payment reservation crossed agencies');$assert(!$row||$row['invoice_id']===null||(int)$row['invoice_agency']===$agencyId,$label.' payment invoice crossed agencies');};
    $assertInvoiceAgency=function(int $invoiceId,string $label)use($assert,$agencyId){$row=dbFetchOne("SELECT i.agency_id,i.customer_id,i.reservation_id,c.agency_id customer_agency,r.agency_id reservation_agency,oi.agency_id original_agency FROM invoices i LEFT JOIN customers c ON c.id=i.customer_id LEFT JOIN reservations r ON r.id=i.reservation_id LEFT JOIN invoices oi ON oi.id=i.original_invoice_id WHERE i.id=:id",['id'=>$invoiceId]);$assert($row&&((int)$row['agency_id']===$agencyId),$label.' invoice row is not in the authoritative agency');$assert(!$row||$row['customer_id']===null||(int)$row['customer_agency']===$agencyId,$label.' invoice customer crossed agencies');$assert(!$row||$row['reservation_id']===null||(int)$row['reservation_agency']===$agencyId,$label.' invoice reservation crossed agencies');$assert(!$row||$row['original_agency']===null||(int)$row['original_agency']===$agencyId,$label.' invoice original invoice crossed agencies');};
    $assertDepositAgency=function(int $depositId,string $label)use($assert,$agencyId){$row=dbFetchOne("SELECT d.agency_id,d.reservation_id,r.agency_id reservation_agency FROM deposits d LEFT JOIN reservations r ON r.id=d.reservation_id WHERE d.id=:id",['id'=>$depositId]);$assert($row&&((int)$row['agency_id']===$agencyId),$label.' deposit row is not in the authoritative agency');$assert(!$row||$row['reservation_id']===null||(int)$row['reservation_agency']===$agencyId,$label.' deposit reservation crossed agencies');};
    $assertExpenseAgency=function(int $expenseId,string $label)use($assert,$agencyId){$row=dbFetchOne("SELECT e.agency_id,e.vehicle_id,v.agency_id vehicle_agency,e.contract_id,r.agency_id contract_agency,e.original_expense_id,oe.agency_id original_agency FROM expenses e LEFT JOIN vehicles v ON v.id=e.vehicle_id LEFT JOIN rental_contracts rc ON rc.id=e.contract_id LEFT JOIN reservations r ON r.id=rc.reservation_id LEFT JOIN expenses oe ON oe.id=e.original_expense_id WHERE e.id=:id",['id'=>$expenseId]);$assert($row&&((int)$row['agency_id']===$agencyId),$label.' expense row is not in the authoritative agency');$assert(!$row||$row['vehicle_id']===null||(int)$row['vehicle_agency']===$agencyId,$label.' expense vehicle crossed agencies');$assert(!$row||$row['contract_id']===null||(int)$row['contract_agency']===$agencyId,$label.' expense contract crossed agencies');$assert(!$row||$row['original_expense_id']===null||(int)$row['original_agency']===$agencyId,$label.' expense original row crossed agencies');};
    $assertAdjustmentAgency=function(int $adjustmentId,string $label)use($assert,$agencyId){$row=dbFetchOne("SELECT a.agency_id,a.payment_id,p.agency_id payment_agency,a.destination_deposit_id,d.agency_id deposit_agency FROM payment_adjustments a LEFT JOIN payments p ON p.id=a.payment_id LEFT JOIN deposits d ON d.id=a.destination_deposit_id WHERE a.id=:id",['id'=>$adjustmentId]);$assert($row&&((int)$row['agency_id']===$agencyId),$label.' adjustment row is not in the authoritative agency');$assert(!$row||$row['payment_id']===null||(int)$row['payment_agency']===$agencyId,$label.' adjustment payment crossed agencies');$assert(!$row||$row['destination_deposit_id']===null||(int)$row['deposit_agency']===$agencyId,$label.' adjustment deposit crossed agencies');};
    $assertDepositEventAgency=function(int $eventId,string $label)use($assert,$agencyId){$row=dbFetchOne("SELECT e.agency_id,e.deposit_id,d.agency_id deposit_agency,e.payment_id,p.agency_id payment_agency FROM deposit_events e LEFT JOIN deposits d ON d.id=e.deposit_id LEFT JOIN payments p ON p.id=e.payment_id WHERE e.id=:id",['id'=>$eventId]);$assert($row&&((int)$row['agency_id']===$agencyId),$label.' deposit event row is not in the authoritative agency');$assert(!$row||$row['deposit_id']===null||(int)$row['deposit_agency']===$agencyId,$label.' deposit event deposit crossed agencies');$assert(!$row||$row['payment_id']===null||(int)$row['payment_agency']===$agencyId,$label.' deposit event payment crossed agencies');};
